    @TempDir Path root;
    @Test void unavailableConstantEffectDiagnosticsNeverPutNaNsIntoAuditDocuments()throws Exception{
        Path source=Files.createDirectories(root.resolve("replication-source"));Files.writeString(source.resolve("replication.tsv"),"feature_id\tdiscovery_dataset\treplication_dataset\tdiscovery_beta\treplication_beta\tdiscovery_selected\treplicated\ng0\ta\tb\t0\t0\tfalse\tfalse\ng1\ta\tb\t0\t0\tfalse\tfalse\n");seal(source,"discovery_replication",Map.of());
        var c=context("constant-review","diagnostic_review",Map.of(),Map.of("replication",source),List.of("a","b"));var r=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,r.state());
        var document=StudyYaml.loadArtifact(c.outputDirectory().resolve("diagnostics.yaml"));var comparison=StudyPublicEvidence.map(StudyPublicEvidence.list(document.get("discovery_replication")).get(0));
        for(String key:List.of("pearson_r","ols_intercept","ols_slope","sd_ratio","replication_fraction"))assertEquals("NA",comparison.get(key),key);
        assertEquals("not_estimable",comparison.get("coefficient_diagnostics_status"));
    }
    private Context context(String name,String type,Map<String,Object> analysis,Map<String,Path> deps,List<String> ids)throws Exception {
        var datasets=new ArrayList<Object>();for(String id:ids)datasets.add(Map.of("id",id,"cohort","cohort-"+id));var op=new LinkedHashMap<String,Object>(Map.of("id",name,"type",type,"hypothesis","H","datasets",ids));if(!ids.isEmpty())op.put("roles",Map.of("discovery",List.of(ids.get(0)),"replication",ids.subList(1,ids.size())));return new Context(root,Files.createDirectories(root.resolve(name)),op,Map.of("resources",Map.of("directory","fixture-resources","network","offline","downloads","deny"),"datasets",datasets,"hypotheses",List.of(Map.of("id","H","inputs",op.getOrDefault("roles",Map.of()),"analysis",analysis))),Map.of(),deps);
    }
    private void seal(Path directory,String type,Map<String,Object> details)throws Exception {var hashes=new LinkedHashMap<String,Object>();try(var paths=Files.walk(directory)){for(Path file:paths.filter(Files::isRegularFile).toList())hashes.put(directory.relativize(file).toString().replace('\\','/'),FollowupSupport.hash(file));}StudyPublicEvidence.write(directory.resolve("manifest.yaml"),Map.of("operation_id",directory.getFileName().toString(),"operation_type",type,"hypothesis","H","state","complete","details",details,"output_sha256",hashes));}
    private Path cohorts(int k)throws Exception {Path producer=Files.createDirectories(root.resolve("cohorts/standard-results"));for(int i=0;i<k;i++){var text=new StringBuilder("feature_id\tbeta\tse\tp_value\tstatus\n");for(int n=0;n<16;n++){boolean hit=(n&(1<<(k-1-i)))!=0;text.append("f").append(n).append('\t').append(i==k-1&&n==15?-1:1).append("\t1\t").append(hit?".001":".7").append("\tok\n");}Files.writeString(producer.resolve(String.valueOf((char)('A'+i))+".tsv"),text);}seal(producer.getParent(),"validate_harmonize",Map.of());return producer.getParent();}
    private static Map<String,Object> plan(Map<String,Object> overlap){return Map.of("multiple_testing",Map.of("method","NONE","alpha",.05),"cohort_overlap",overlap);}
    @Test void exactFourWayPatternsAndDegreeCountsRetainDirectionAndCompleteFamilies()throws Exception {
        Path input=cohorts(4);String original=FollowupSupport.hash(input.resolve("standard-results/A.tsv"));var c=context("four","cohort_overlap",plan(Map.of()),Map.of("cohorts",input),List.of("A","B","C","D"));var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());var patterns=DelimitedData.readResult(c.outputDirectory().resolve("cohort-overlap-patterns.tsv"));assertEquals(16,patterns.rows().size());assertTrue(patterns.rows().stream().allMatch(row->row[patterns.column("features")].equals("1")));var degrees=DelimitedData.readResult(c.outputDirectory().resolve("cohort-overlap-degree.tsv"));assertEquals(List.of("1","4","6","4","1"),degrees.rows().stream().map(row->row[degrees.column("exact_features")]).toList());assertEquals(16,result.details().get("common_estimable_features"));var features=DelimitedData.readResult(c.outputDirectory().resolve("cohort-overlap-features.tsv"));assertEquals("opposite_selected_effect_directions",features.rows().stream().filter(row->row[0].equals("f15")).findFirst().orElseThrow()[features.column("direction_context")]);assertTrue(Files.size(c.outputDirectory().resolve("cohort-overlap-upset.pdf"))>1000);assertFalse(Files.exists(c.outputDirectory().resolve("cohort-overlap-venn.png")));assertEquals(original,FollowupSupport.hash(input.resolve("standard-results/A.tsv")));
    }
