    private Path meta(String folder,int n,double[] i2,String definition,boolean missingQ)throws Exception {Path d=Files.createDirectories(root.resolve(folder));var text=new StringBuilder("feature_id\tterm\tbeta\tse\tp_value\tn_cohorts\tq\tq_df\tq_p_value\ti_squared\ttau_squared\tci_lower\tci_upper\tstatus\tq_definition\n");for(int i=0;i<n;i++)text.append("f").append(i).append("\tpooled\t1\t.2\t.000001\t3\t4\t2\t").append(missingQ&&i==0?"NA":i==0?".01":".6").append('\t').append(i2==null?"NA":i2[i]).append("\t.1\t.6\t1.4\tok\t").append(definition).append('\n');Path file=d.resolve("meta-analysis.tsv");Files.writeString(file,text);return file;}
