    @Test void suppliedHeterogeneityKeepsItsSourceCutoffAndUnknownRulesRemainUnavailable()throws Exception {
        Files.writeString(root.resolve("provided-heterogeneity.tsv"),"feature_id\tmetric\tmetric_value\tin_alert_scope\thigh_heterogeneity\nf1\ti_squared\t55\ttrue\tfalse\nf2\ti_squared\t10\ttrue\tfalse\n");var rule=Map.of("metric","i_squared","minimum_sources",2,"feature_scope","all_estimable","minimum_features",1,"minimum_high_features",1,"widespread_fraction",.5,"fraction_comparison","greater_than_or_equal","i_squared_threshold",60);var definition=new LinkedHashMap<String,Object>(Map.of("id","provided","kind","heterogeneity_review","files",Map.of("results","provided-heterogeneity.tsv"),"scope",Map.of("datasets",List.of("A","B")),"method",Map.of("name","External heterogeneity assessment","parameters",Map.of("alert_rule",rule)),"family",Map.of("id","source-heterogeneity","coverage","complete","tested_count",2,"adjustment","NONE")));var c=supplied("provided-heterogeneity","heterogeneity_review",definition);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());var summary=StudyYaml.loadArtifact(c.outputDirectory().resolve("heterogeneity-review.yaml"));assertEquals(true,summary.get("assessment_complete"));assertEquals(false,summary.get("widespread_alert"));assertEquals(60,StudyPublicEvidence.map(summary.get("source_alert_rule")).get("i_squared_threshold"));definition.put("method",Map.of("name","External assessment without a declared alert rule"));var missing=supplied("provided-rule-unknown","heterogeneity_review",definition);assertEquals(State.COMPLETE,new StudyCliExecutor().execute(missing).state());var unknown=StudyYaml.loadArtifact(missing.outputDirectory().resolve("heterogeneity-review.yaml"));assertEquals("unavailable",unknown.get("widespread_alert"));assertEquals(false,unknown.get("assessment_complete"));
    }
