        Path input=cohorts(3),primary=meta("retained-primary",10,new double[10],"cochran_q",false);seal(primary.getParent(),"meta_analysis",Map.of());var analysis=Map.<String,Object>of("heterogeneity",Map.of("minimum_retained_cohorts",3));var c=context("retained","sensitivity_analysis",analysis,Map.of("inputs",input,"primary",primary.getParent()),List.of("A","B","C"));var op=new LinkedHashMap<>(c.operation());op.put("configuration",Map.of("automatic_leave_one_cohort_out",true));c=new Context(c.project(),c.outputDirectory(),op,c.study(),Map.of(),c.dependencyDirectories());var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());var attempts=StudyPublicEvidence.list(result.details().get("analyses"));assertEquals(3,attempts.size());assertTrue(attempts.stream().map(StudyPublicEvidence::map).allMatch(a->"not_applicable".equals(a.get("status"))));try(var files=Files.walk(c.outputDirectory())){assertEquals(0,files.filter(path->path.getFileName().toString().equals("meta-analysis.tsv")).count());}
